"version\"\n              ],\n              \"additionalProperties\": false\n            }\n          ]\n        },\n        \"components\": {\n          \"type\": \"object\",\n          \"properties\": {\n            \"health\": {\n              \"type\": \"number\"\n            },\n            \"contactDamage\": {\n              \"type\": \"number\"\n            }\n          },\n          \"required\": [\n            \"health\",\n            \"contactDamage\"\n          ],\n          \"additionalProperties\": false\n        },\n        \"parts\": {\n          \"type\": \"array\",\n          \"items\": {\n            \"type\": \"object\",\n            \"properties\": {\n              \"shape\": {\n                \"type\": \"string\",\n                \"enum\": [\n                  \"box\",\n                  \"blade\"\n                ]\n              },\n              \"offset\": {\n                \"type\": \"object\",\n                \"properties\": {\n                  \"x\": {\n                    \"type\": \"number\"\n                  },\n                  \"y\": {\n                    \"type\": \"number\"\n                  },\n                  \"z\": {\n                    \"type\": \"number\"\n                  }\n                },\n                \"required\": [\n                  \"x\",\n                  \"y\",\n                  \"z\"\n                ],\n                \"additionalProperties\": false\n              },\n              \"size\": {\n                \"type\": \"object\",\n                \"properties\": {\n                  \"x\": {\n                    \"type\": \"number\"\n                  },\n                  \"y\": {\n                    \"type\": \"number\"\n                  },\n                  \"z\": {\n                    \"type\": \"number\"\n                  }\n                },\n                \"required\": [\n                  \"x\",\n                  \"y\",\n                  \"z\"\n                ],\n                \"additionalProperties\": false\n              },\n              \"material\": {\n                \"type\": \"string\",\n                \"enum\": [\n                  \"grass\",\n                  \"dirt\",\n                  \"stone\",\n                  \"wood\",\n                  \"leaves\",\n                  \"planks\",\n                  \"sand\",\n                  \"brick\",\n                  \"light\",\n                  \"glass\",\n                  \"solid\"\n                ]\n              },\n              \"color\": {\n                \"type\": \"string\"\n              },\n              \"solid\": {\n                \"type\": \"boolean\"\n              }\n            },\n            \"required\": [\n              \"shape\",\n              \"offset\",\n              \"size\",\n              \"material\",\n              \"color\",\n              \"solid\"\n            ],\n            \"additionalProperties\": false\n          }\n        }\n      },\n      \"required\": [\n        \"id\",\n        \"name\",\n        \"position\",\n        \"source\",\n        \"components\",\n        \"parts\"\n      ],\n      \"additionalProperties\": false\n    }\n  }\n}",
